import json, sys, re, os
base = os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
tax = json.load(open(os.path.join(base, 'taxonomy.json')))
inputs = {x['id']: x for x in json.load(open(os.path.join(base, 'inputs.json')))}
ids = sys.argv[1:]
bad = re.compile(r'0\(0\)|00\(00\)|;0:|Vol 00|XX\(X\)|\[|—')
for i in ids:
    errs = []
    try:
        r = json.load(open(os.path.join(base, 'verified', i + '.json')))
    except Exception as e:
        print(i, 'JSON ERROR', e); continue
    if r.get('id') != i: errs.append('id')
    if r['sourceFile'] != inputs[i]['sourceFile']: errs.append('sourceFile')
    if r['decision'] != 'EXCLUDE':
        if r['paper']['doi'] != inputs[i]['externalDoi'].lower(): errs.append('doi')
        if r['doiMissing'] is not False: errs.append('doiMissing')
        if r['studyDesign'] not in tax['studyDesigns']: errs.append('design')
        if r['primaryDomain'] not in r['domains']: errs.append('primary not in domains')
        for k, t in [('domains', 'domains'), ('audiences', 'audiences'), ('sports', 'sports'), ('populations', 'populations')]:
            for v in r[k]:
                if v not in tax[t]: errs.append(k + ':' + v)
    v = r.get('verification', {})
    for k in ['status', 'changes', 'residualConcerns', 'spotCheckPriority']:
        if k not in v: errs.append('verif.' + k)
    if v.get('status') not in ('VERIFIED', 'CORRECTED', 'DECISION_CHANGED'): errs.append('status')
    text = json.dumps({k: r[k] for k in r if k != 'verification'}, ensure_ascii=False)
    if bad.search(text): errs.append('placeholder/emdash: ' + bad.search(text).group(0))
    if '—' in json.dumps(r, ensure_ascii=False): errs.append('emdash in verification')
    print(i, r['decision'], v.get('status'), v.get('spotCheckPriority'), 'OK' if not errs else errs)

